/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void timeout_start (Timeout timeout)
{
  CRITICAL ;

  C_ENTER ;
    {
      if(timeout)
        {
          timeout->timeout_count = timeout->timeout_assigned ;
          
          if (timeout->timeout_func)
            {
              timeout->timeout_func_done = FALSE ;
            }  	
          else
            {
              timeout->timeout_func_done = TRUE ;
            } 
        }
      else
        {
          
        }
    }
  C_LEAVE ;
}

